mapper.insert:
INSERT INTO prediction (equipment_id, data_ts, batch_id, failure_prob)
SELECT #{equipmentId}, #{dataTs}, #{batchId}, #{failureProb}
WHERE NOT EXISTS (
SELECT 1
FROM prediction
WHERE equipment_id = #{equipmentId}
AND data_ts = #{dataTs}
)

mapper.select:
SELECT TOP (#{limit}) data_ts, failure_prob
FROM prediction
WHERE equipment_id = #{equipmentId}
AND data_ts < #{beforeTs}
ORDER BY data_ts DESC

SELECT equipment_id, data_ts, batch_id, failure_prob
FROM prediction
WHERE equipment_id = #{equipmentId}
AND data_ts >= #{from}
AND data_ts < #{to}
ORDER BY data_ts
